  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': '画面を接続する',
  'simple.help.g1.s1': '使用するテレビ、タブレット、パソコンでプレーヤーを開きます。Android アプリをインストールするか、ブラウザでこのサイトの /player ページを開いてください。',
  'simple.help.g1.s2': '手元にテレビがない場合は、別のブラウザタブでプレーヤーを開いて試せます。',
  'simple.help.g1.s3': 'プレーヤーに 6 桁のコードが表示されます。ここで「画面を追加」を選び、そのコードを入力します。',
  'simple.help.g1.s4': '「店頭ウィンドウ」のように、分かりやすい名前を画面に付けます。',
  'simple.help.g2.title': '画面に表示する内容を変更する',
  'simple.help.g2.s1': '「画面に表示する内容を変更」を選ぶか、「あなたの画面」で画面をタップします。',
  'simple.help.g2.s2': '新しいものだけを表示するには「置き換え」、今の内容に加えるには「追加」を選びます。',
  'simple.help.g2.s3': '写真や動画をアップロードするか、アップロード済みのものを選ぶか、別の画面と同じ内容を表示します。',
  'simple.help.g2.s4': '数秒で画面が更新されます。',
  'simple.help.g3.title': '写真と動画をアップロードする',
  'simple.help.g3.s1': '「写真をアップロード」を選び、ファイルを好きなだけ選ぶか、ドラッグして入れます。',
  'simple.help.g3.s2': '表示する画面にチェックを入れます。後で使う場合はすべてのチェックを外します。',
  'simple.help.g3.s3': '写真は 1 枚 10 秒表示され、動画は最後まで再生されます。',
  'simple.help.q1': '画面として何が使えますか？',
  'simple.help.a1': 'Android テレビ、TV ボックスやタブレット、Fire TV、LG・Samsung のスマートテレビ、Raspberry Pi、Windows、ChromeOS、またはウェブブラウザのある任意の機器です。',
  'simple.help.q2': '画面が変わりません。何を確認すればよいですか？',
  'simple.help.a2': 'ホームで画面が「再生中」になっているか確認してください。「オフライン」の場合は、機器の電源とインターネット接続を確認してください。再接続するとすぐに変更が反映されます。',
  'simple.help.q3': 'インターネットが切れたらどうなりますか？',
  'simple.help.a3': '画面はコンテンツを端末に保存しており、そのまま再生を続けます。接続が戻ると新しい変更が届きます。',
  'simple.help.q4': 'どのファイルをアップロードできますか？',
  'simple.help.a4': '写真（JPEG、PNG、GIF、WebP）と動画（MP4 が最適）、そして音声です。PDF は「詳細」表示のコンテンツページからアップロードできます。',
  'simple.help.q5': '画面の名前を変更したり、削除したりするには？',
  'simple.help.a5': '右上で「詳細」に切り替え、「画面」を開いて画面をクリックし、ページ上部の「名前を変更」または「削除」を使います。',
  'simple.help.q6': '時間帯ごとに違うものを表示できますか？',
  'simple.help.a6': 'はい。「詳細」表示の「スケジュール」で設定できます。シンプル表示では、変更するまで画面には同じ内容が表示され続けます。',
  'simple.help.trial_q': '無料トライアルの仕組みは？',
  'simple.help.trial_a': 'Pro プランを 14 日間、すべての機能を使って試せます。カードは不要です。終了後は Free プランに移行します。何も削除されず、Free プランの上限を超えた画面はプランを選ぶまで一時停止します。',
  'stats.prompt.title': 'ScreenTinker の利用状況の把握にご協力いただけますか？',
  'stats.prompt.body': 'ほとんどのインストールは非公開のため、画面がいくつあるか分かりません。共有すると、ランダムな ID、バージョン、画面の数だけを送信します。それ以外は一切送りません。設定からいつでも変更できます。',
